    if (a === 'lmf') { lmFilter = el.getAttribute('data-v'); renderLm(); }
    else if (a === 'lmgo') lmGo(+id);
    else if (a === 'tab') setTab(el.getAttribute('data-v'));
    else if (a === 'chatd') { chatD = +el.getAttribute('data-d'); openChat('n'); }
    else if (a === 'post') { chatD = +el.getAttribute('data-d'); openFeed(); $('feedTxt').focus(); }
    else if (a === 'whisper') { whisperTo = id; openChat('w'); $('quickIn').focus(); }
    else if (a === 'follow') toggleFollow(id);
    else if (a === 'goto') gotoUser(id);
    else if (a === 'user') { whisperTo = id; $('users').hidden = false; renderUsers(); }
    else if (a === 'like') { if (!me) { toast('먼저 입장하세요'); return; } updPost(id, function (p) { var i = p.likes.indexOf(me.id); if (i >= 0) p.likes.splice(i, 1); else p.likes.push(me.id); }); }
